/* 修正 No.53 (2026-04-24): ブラウザネイティブの confirm() を
   サイトの配色・角丸に合わせた独自モーダルへ置き換える。 */
import { ChangeDetectionStrategy, Component, Inject, HostListener } from '@angular/core';
import { CommonModule } from '@angular/common';
import { MAT_DIALOG_DATA, MatDialogRef } from '@angular/material/dialog';

export interface ConfirmDialogData {
  title?: string;
  message: string;
  confirmText?: string;
  cancelText?: string;
  danger?: boolean;
}

@Component({
  selector: 'app-confirm-dialog',
  standalone: true,
  imports: [CommonModule],
  templateUrl: './confirm-dialog.component.html',
  styleUrls: ['./confirm-dialog.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class ConfirmDialogComponent {
  constructor(
    @Inject(MAT_DIALOG_DATA) public data: ConfirmDialogData,
    private dialogRef: MatDialogRef<ConfirmDialogComponent, boolean>,
  ) {}

  get title(): string {
    return this.data?.title || '確認';
  }
  get message(): string {
    return this.data?.message || '';
  }
  get confirmText(): string {
    return this.data?.confirmText || 'OK';
  }
  get cancelText(): string {
    return this.data?.cancelText || 'キャンセル';
  }
  get danger(): boolean {
    return !!this.data?.danger;
  }

  onConfirm(): void {
    this.dialogRef.close(true);
  }

  onCancel(): void {
    this.dialogRef.close(false);
  }

  @HostListener('document:keydown.escape')
  onEscape(): void {
    this.onCancel();
  }
}
