/* 修正 No.53 (2026-04-24): ブラウザネイティブ confirm() を
   サイトデザインに揃えた共通モーダルへ置き換える。 */
/**
 * 既存の確認ダイアログ. STEP 8 / Phase 3.1 で導入された OverlayManagerService と
 * 並行運用. 既存 modal は維持, 新規 modal は OverlayManagerService を推奨.
 */
import { Injectable, inject } from '@angular/core';
import { MatDialog } from '@angular/material/dialog';
import {
  ConfirmDialogComponent,
  ConfirmDialogData,
} from '../components/confirm-dialog/confirm-dialog.component';

export interface ConfirmOptions {
  title?: string;
  message: string;
  confirmText?: string;
  cancelText?: string;
  /** true の場合 削除系の赤ボタンで表示する */
  danger?: boolean;
}

@Injectable({ providedIn: 'root' })
export class ConfirmDialogService {
  private dialog = inject(MatDialog);

  confirm(options: ConfirmOptions): Promise<boolean> {
    const data: ConfirmDialogData = {
      title: options.title,
      message: options.message,
      confirmText: options.confirmText || (options.danger ? '削除' : 'OK'),
      cancelText: options.cancelText || 'キャンセル',
      danger: options.danger,
    };
    const ref = this.dialog.open<ConfirmDialogComponent, ConfirmDialogData, boolean>(
      ConfirmDialogComponent,
      {
        data,
        panelClass: 'confirm-dialog-panel',
        backdropClass: 'confirm-dialog-backdrop',
        width: 'auto',
        maxWidth: '92vw',
        autoFocus: true,
        restoreFocus: true,
        disableClose: false,
      },
    );
    return ref.afterClosed().toPromise().then(v => !!v);
  }
}
